# -*- coding: utf-8 -*-
# make_fill_data_171m.py : ONE workbook holding both rounds of the ZCRMR171 test (v0.01 1차 + v0.02 재테스트).
#   Merges the two payloads already generated by make_fill_data_171.py / make_fill_data_171b.py.
import io, json

A = json.load(io.open(r"C:\sap-test\results\_fill_data_171.json", encoding="utf-8"))    # v0.01
B = json.load(io.open(r"C:\sap-test\results\_fill_data_171b.json", encoding="utf-8"))   # v0.02
OUT = r"C:\sap-test\results\_fill_data_171m.json"

old = {r["id"]: r for r in A["prog_rows"]}
rows = []
changed = []
for r in B["prog_rows"]:
    r = dict(r)
    o = old[r["id"]]
    r["data"] = r["data"].replace("[1차 결과 유지 - 이번 수정과 무관, 재수행 안 함] ", "[v0.01] ").replace("[재테스트 09-18 저녁, 수정본] ", "[v0.02 재테스트] ")
    if o["result"] != r["result"]:
        changed.append(r["id"])
        r["data"] += "\n〔v0.01 결과: %s〕 %s" % (o["result"] or "미실행", o["data"])
    elif r["data"].startswith("[v0.02 재테스트]"):
        r["data"] += "\n〔v0.01 결과: %s〕" % (o["result"] or "미실행")
    rows.append(r)

FIXNOTE = {
    "TC-25 / TC-26 / TC-27 / TC-33": ("\n[v0.02 조치결과] 개발 수정(재검증 실패 시 RETURN) 후 재테스트 PASS - TC-25·26·27 전표 미생성, TC-33 역분개 없음(BKPF STBLG 공백). 다중 선택도 전체 미처리.",
                                      ["S20_R25_r_tc25_after.png", "S20_R27_r_tc27_after.png", "S12_BKPF_r_fi_tc33.png"]),
    "X-01 / X-02": ("\n[v0.02 조치결과] 개발 수정(검증 LOOP / 처리 LOOP 분리) 후 재테스트 PASS - 한 건이라도 불일치면 전체 미처리, ZCRM_RECPTF 변화 없음.",
                    ["S20_RX1_r_x1_after.png", "S20_RX2_r_x2_after.png"]),
    "X-03": ("\n[v0.02 조치결과] 재테스트 PASS - '구독 화면에 비구독 상담건이 포함되어 있습니다.' / '일반 화면에 구독 상담건이 포함되어 있습니다.' 가 정상 표시.",
             ["S20_R08_r_tc08_after.png"]),
    "TC-23": ("\n[v0.02 조치결과] 재테스트 PASS - 정산 ALV 에 Message 컬럼 추가, FI 오류 내용 표시.", ["S20_R23_r_tc23_after.png"]),
}
THB = r"C:\sap-test\results\shots\_tpl_171b" + "\\"
fails = []
for f in A["fail_rows"]:
    f = dict(f)
    note, imgs = FIXNOTE[f["id"]]
    f["case"] = "[v0.01 FAIL → v0.02 PASS] " + f["case"]
    f["detail"] += note
    f["image_paths"] = list(f["image_paths"]) + [THB + i for i in imgs]
    fails.append(f)

ev = [dict(e, tc="[v0.01] " + e["tc"]) for e in A["evidence"]] + [dict(e, tc="[v0.02] " + e["tc"]) for e in B["evidence"]]

payload = dict(B)
payload["prog_rows"] = rows
payload["fail_rows"] = fails
payload["evidence"] = ev
payload["revision"] = {
    "B5": "0.01", "C5": "ZCRMR171 일시불구독 개선(ZCRM171S) 본사확정·FI 처리 테스트 최초 작성 (50건: PASS 41 / FAIL 8 / 미실행 1)", "D5": "2026.09.18", "E5": "※작성자 기입 필요", "F5": "", "G5": "",
    "B6": "0.02", "C6": "FAIL 8건(재검증 차단 TC-25·26·27·33, 부분처리 X-01·02, 메시지 X-03·TC-23) 개발 수정 후 재테스트 → 전건 PASS (PASS 49 / 미실행 1)", "D6": "2026.09.18", "E6": "※작성자 기입 필요", "F6": "", "G6": "",
}
payload["prog_header"] = dict(B["prog_header"], B2="SR03000035400 ZCRMR171 일시불구독 개선 - 본사확정 및 FI 처리 (ZCRM171 / ZCRM171S)")
payload["legend"] = {
    "blank": "결과란은 최신(v0.02) 기준이다. 테스트 데이터 열의 '[v0.01]' 은 1차(09-18 새벽) 결과를 그대로 둔 행, '[v0.02 재테스트]' 는 수정본으로 다시 수행한 행이며 〔v0.01 결과: …〕 에 1차 판정을 남겼다. 결과란이 비어 있으면 미실행.",
    "note": "KDQ 210. v0.01 = 2026-09-18 새벽 1차, v0.02 = 2026-09-18 22시 재테스트(같은 테스트 데이터, 기간월 2026.09). 증적 시트는 [v0.01] → [v0.02] 순서. FAIL내역은 1차 FAIL 4묶음(8건)과 v0.02 조치결과를 함께 적었다. "
            "남은 정리 사항(결함 아님): ZCRM_RECPTF (202609 / 0000100036 / S) 에 이미 역분개된 전표번호 3100069924 가 남아 있음 - 개발자 정리 필요.",
}
io.open(OUT, "w", encoding="utf-8").write(json.dumps(payload, ensure_ascii=False, indent=1))
res = [r["result"] for r in rows]
print("rows", len(rows), "PASS", res.count("PASS"), "FAIL", res.count("FAIL"), "미실행", res.count(""), "changed:", changed)
print("fail rows", len(fails), "evidence", len(ev))
